/* Turkmen Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Serdar": "commander, chief — Persian", "Aygul": "moon flower — Turkic ay (moon) + gul (flower)", "Merdan": "brave man — Persian", "Jennet": "paradise — Arabic jannah", "Batyr": "hero — Turkic", "Maral": "deer — Turkic/Persian", "Berdimuhamedow": "Family name of Gurbanguly Berdimuhamedow, former president of Turkmenistan.", "Niyazow": "Family name of Saparmurat Niyazow, first president of Turkmenistan.", "Atayew": "A common Turkmen surname form.", "Durdyyev": "A common Turkmen surname form."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Serdar';
console.log(lookup(q));

